package daemon_test

import (
	"net/url"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/wesm/kata/internal/testenv"
)

func TestSearchEndpoint_ReturnsHitsWithScores(t *testing.T) {
	env := testenv.New(t)
	pid := initWorkspaceViaHTTP(t, env, "https://github.com/wesm/kata.git")
	createIssueViaHTTP(t, env, pid, "fix login crash on Safari")
	createIssueViaHTTP(t, env, pid, "unrelated")

	resp, bs := envGetRaw(t, env, projectPath(pid)+"/search?q="+url.QueryEscape("login Safari"))
	require.Equal(t, 200, resp.StatusCode)
	body := string(bs)
	assert.Contains(t, body, `"query":"login Safari"`)
	assert.Contains(t, body, `"title":"fix login crash on Safari"`)
	assert.Contains(t, body, `"matched_in"`)
	assert.NotContains(t, body, `"title":"unrelated"`,
		"unrelated issue should not appear in results")
}

func TestSearchEndpoint_EmptyQueryIsValidationError(t *testing.T) {
	env := testenv.New(t)
	pid := initWorkspaceViaHTTP(t, env, "https://github.com/wesm/kata.git")

	resp, bs := envGetRaw(t, env, projectPath(pid)+"/search?q=")
	assertAPIError(t, resp.StatusCode, bs, 400, "validation")
}

func TestSearchEndpoint_UnknownProjectIs404(t *testing.T) {
	env := testenv.New(t)
	resp, bs := envGetRaw(t, env, "/api/v1/projects/9999/search?q=anything")
	assertAPIError(t, resp.StatusCode, bs, 404, "project_not_found")
}

// TestSearchEndpoint_EmptyResultsIsArrayNotNull pins the wire shape: a
// search with no matches must return "results":[] (a JSON array, possibly
// empty), not "results":null. CLI consumers iterate over the slice and a
// future regression that flipped to `var hits []SearchHit` would silently
// emit null and break clients that assume an array.
func TestSearchEndpoint_EmptyResultsIsArrayNotNull(t *testing.T) {
	env := testenv.New(t)
	pid := initWorkspaceViaHTTP(t, env, "https://github.com/wesm/kata.git")

	resp, bs := envGetRaw(t, env, projectPath(pid)+"/search?q=zxqyq-no-such-token")
	require.Equal(t, 200, resp.StatusCode)
	body := string(bs)
	assert.Contains(t, body, `"results":[]`,
		"empty results must serialize as an array, not null")
	assert.NotContains(t, body, `"results":null`)
}

package api_test

import (
	"encoding/json"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/wesm/kata/internal/api"
)

// TestAPIError_WireShape pins the on-the-wire JSON envelope shape so a future
// refactor (e.g., struct-tag changes, MarshalJSON edits, or moving to a
// different framework writer) can't silently regress to flat or PascalCase
// fields. The CLI parser depends on this exact shape.
func TestAPIError_WireShape(t *testing.T) {
	e := api.NewError(404, "project_not_found", "msg", "hint", map[string]any{"k": "v"})
	bs, err := json.Marshal(e)
	require.NoError(t, err)

	var got map[string]any
	require.NoError(t, json.Unmarshal(bs, &got))
	assert.EqualValues(t, 404, got["status"])
	inner, ok := got["error"].(map[string]any)
	require.True(t, ok, "error should be an object")
	assert.Equal(t, "project_not_found", inner["code"])
	assert.Equal(t, "msg", inner["message"])
	assert.Equal(t, "hint", inner["hint"])
	assert.Equal(t, map[string]any{"k": "v"}, inner["data"])
}

package main

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestSearch_ReturnsMatchedIssues(t *testing.T) {
	env, dir, pid := setupCLIWorkspace(t)
	createIssue(t, env, pid, "fix login crash on Safari")
	createIssue(t, env, pid, "unrelated issue")

	out := runCLI(t, env, dir, "search", "login Safari")
	assert.Contains(t, out, "fix login crash on Safari")
	assert.NotContains(t, out, "unrelated issue")
}

func TestSearch_EmptyQueryIsValidationError(t *testing.T) {
	f := newCLIFixture(t)
	_ = requireCLIError(t, f.execute("search", "  "), ExitValidation)
}

// TestSearch_UnquotedMultiTerm verifies that `kata search login Safari`
// (no quotes) joins the args with spaces and matches the same way as the
// quoted form. Required by the BM25 implicit-AND contract.
func TestSearch_UnquotedMultiTerm(t *testing.T) {
	env, dir, pid := setupCLIWorkspace(t)
	createIssue(t, env, pid, "fix login crash on Safari")
	createIssue(t, env, pid, "unrelated issue")

	out := runCLI(t, env, dir, "search", "login", "Safari")
	assert.Contains(t, out, "fix login crash on Safari")
	assert.NotContains(t, out, "unrelated issue")
}

// TestSearch_RejectsNonPositiveLimit covers hammer-test #5: --limit
// 0/-1 used to be silently treated as "no limit" because
// buildSearchURL only set the param when limit > 0. Now mirrors
// list/ready/events/daemon-logs validation.
func TestSearch_RejectsNonPositiveLimit(t *testing.T) {
	for _, lim := range []string{"0", "-1"} {
		_, err := runCmdOutput(t, nil, "search", "x", "--limit", lim)
		_ = requireCLIError(t, err, ExitValidation)
	}
}

// Internal test for the unexported foldDetailsIntoMessage helper
// and the public InstallErrorFormatter contract.
//
//nolint:revive // package-name lint flagged externally; internal test needs the package name
package api

import (
	"errors"
	"testing"

	"github.com/danielgtaylor/huma/v2"
	"github.com/stretchr/testify/assert"
)

func humaErr(loc, msg string) error {
	return &huma.ErrorDetail{Location: loc, Message: msg}
}

// TestFoldDetailsIntoMessage covers hammer-test finding #11: a
// validation failure used to surface "validation failed" with no
// detail because InstallErrorFormatter dropped huma's per-field
// errs slice. Now folds up to 3 details into the message in
// "field: reason" form so close --reason banana, list --status
// nonsense, etc. give the user actionable feedback.
func TestFoldDetailsIntoMessage(t *testing.T) {
	tests := []struct {
		name     string
		errs     []error
		expected string   // exact match when non-empty
		contains []string // substrings that must appear in output
	}{
		{
			name:     "no details returns base message",
			errs:     nil,
			expected: "validation failed",
		},
		{
			name:     "ErrorDetailer with location surfaces field name",
			errs:     []error{humaErr("body.reason", "expected one of done, wontfix, duplicate")},
			expected: "validation failed: reason: expected one of done, wontfix, duplicate",
		},
		{
			name: "path. and query. prefixes also stripped",
			errs: []error{
				humaErr("query.status", "expected enum value"),
				humaErr("path.id", "must be integer"),
			},
			contains: []string{"status: expected enum value", "id: must be integer"},
		},
		{
			name:     "plain error falls back to .Error()",
			errs:     []error{errors.New("custom")},
			expected: "validation failed: custom",
		},
		{
			name: "more than three details gets and-N-more suffix",
			errs: []error{
				humaErr("body.a", "x"),
				humaErr("body.b", "x"),
				humaErr("body.c", "x"),
				humaErr("body.d", "x"),
				humaErr("body.e", "x"),
			},
			contains: []string{"(and 2 more)"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := foldDetailsIntoMessage("validation failed", tt.errs)
			if tt.expected != "" {
				assert.Equal(t, tt.expected, got)
			}
			for _, sub := range tt.contains {
				assert.Contains(t, got, sub)
			}
		})
	}
}

// TestInstallErrorFormatter_FoldsDetailsIntoApiError pins that
// InstallErrorFormatter's huma.NewError replacement actually wires
// up the fold for code paths that go through the framework's
// validation pipeline.
func TestInstallErrorFormatter_FoldsDetailsIntoApiError(t *testing.T) {
	InstallErrorFormatter()
	// huma.NewError is the package-level function we replaced.
	se := huma.NewError(400, "validation failed",
		&huma.ErrorDetail{Location: "body.reason", Message: "must be one of done, wontfix"})
	apiErr, ok := se.(*APIError)
	if !ok {
		t.Fatalf("expected *APIError, got %T", se)
	}
	assert.Equal(t, 400, apiErr.Status)
	assert.Equal(t, "validation", apiErr.Code)
	assert.Contains(t, apiErr.Message, "reason: must be one of done, wontfix",
		"the per-field detail must reach the wire envelope")
}

package db_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/wesm/kata/internal/db"
)

func TestFTS_IssueInsertIsIndexed(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	createTesterIssueWithBody(ctx, t, d, p.ID, "fix login crash", "stack trace here")

	assertRowCount(ctx, t, d, 1, "FTS should index issue.title on insert",
		`SELECT count(*) FROM issues_fts WHERE issues_fts MATCH 'login'`)
	assertRowCount(ctx, t, d, 1, "FTS should index issue.body on insert",
		`SELECT count(*) FROM issues_fts WHERE issues_fts MATCH 'trace'`)
}

func TestFTS_IssueUpdateReindexes(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	issue := createTesterIssueWithBody(ctx, t, d, p.ID, "old title", "initial body content")

	newTitle := "fresh title"
	_, _, _, err := d.EditIssue(ctx, db.EditIssueParams{
		IssueID: issue.ID, Title: &newTitle, Actor: "tester",
	})
	require.NoError(t, err)

	assertRowCount(ctx, t, d, 0, "old title tokens must be gone after edit",
		`SELECT count(*) FROM issues_fts WHERE issues_fts MATCH 'old'`)
	assertRowCount(ctx, t, d, 1, "new title tokens must be searchable after edit",
		`SELECT count(*) FROM issues_fts WHERE issues_fts MATCH 'fresh'`)
}

func TestFTS_CommentInsertReindexes(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	issue := createTesterIssueWithBody(ctx, t, d, p.ID, "boring", "body")
	addTesterComment(ctx, t, d, issue.ID, "watermelon")

	assertRowCount(ctx, t, d, 1, "comment body must be searchable after insert",
		`SELECT count(*) FROM issues_fts WHERE issues_fts MATCH 'watermelon'`)
}

func TestSearchFTS_RanksByBM25(t *testing.T) {
	d, ctx, p := setupTestProject(t)

	// Three issues. Only the first two mention "login"; the second has it
	// many more times. Issue 1's body is padded with unrelated text so token
	// density makes issue 2's BM25 win unambiguous regardless of column-length
	// normalization quirks.
	createTesterIssueWithBody(ctx, t, d, p.ID, "fix login crash",
		"stack trace from a totally unrelated incident with many tokens to dilute density and dominate length normalization here")
	createTesterIssueWithBody(ctx, t, d, p.ID, "login is broken on login screen",
		"login fails twice login login login")
	createTesterIssueWithBody(ctx, t, d, p.ID, "unrelated issue", "no match here")

	got, err := d.SearchFTS(ctx, p.ID, "login", 20, false)
	require.NoError(t, err)
	assert.Len(t, got, 2)
	// The doubly-mentioned issue should outrank the singly-mentioned one.
	assert.Equal(t, int64(2), got[0].Issue.Number, "more matches → higher rank")
	assert.Equal(t, int64(1), got[1].Issue.Number)
	// Issue 2 has "login" in both title and body; issue 1 has it only in title.
	assert.Equal(t, []string{"title", "body"}, got[0].MatchedIn,
		"issue 2 has login in title AND body")
	assert.Equal(t, []string{"title"}, got[1].MatchedIn,
		"issue 1 has login only in title")
}

func TestSearchFTS_MatchedIn_Comments(t *testing.T) {
	d, ctx, p := setupTestProject(t)

	// Issue body does NOT contain the search term; only the comment does.
	issue := createTesterIssueWithBody(ctx, t, d, p.ID, "unrelated", "nothing here")
	addTesterComment(ctx, t, d, issue.ID, "watermelon found")

	got, err := d.SearchFTS(ctx, p.ID, "watermelon", 20, false)
	require.NoError(t, err)
	require.Len(t, got, 1)
	assert.Equal(t, []string{"comments"}, got[0].MatchedIn,
		"term appears only in a comment")
}

func TestSearchFTS_MatchedIn_AllThreeColumns(t *testing.T) {
	d, ctx, p := setupTestProject(t)

	issue := createTesterIssueWithBody(ctx, t, d, p.ID, "watermelon title", "watermelon body")
	addTesterComment(ctx, t, d, issue.ID, "watermelon comment")

	got, err := d.SearchFTS(ctx, p.ID, "watermelon", 20, false)
	require.NoError(t, err)
	require.Len(t, got, 1)
	assert.Equal(t, []string{"title", "body", "comments"}, got[0].MatchedIn,
		"matched_in must list columns in title/body/comments order")
}

func TestSearchFTS_FiltersByProject(t *testing.T) {
	d, ctx, p1 := setupTestProject(t)
	p2 := createProject(ctx, t, d, "p2", "p2")

	createTesterIssueWithBody(ctx, t, d, p1.ID, "login bug", "")
	createTesterIssueWithBody(ctx, t, d, p2.ID, "login bug", "")

	got, err := d.SearchFTS(ctx, p1.ID, "login", 20, false)
	require.NoError(t, err)
	require.Len(t, got, 1)
	assert.Equal(t, p1.ID, got[0].Issue.ProjectID)
}

func TestSearchFTS_ExcludesDeletedByDefault(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	keep := createTesterIssueWithBody(ctx, t, d, p.ID, "keep login", "")
	gone := createTesterIssueWithBody(ctx, t, d, p.ID, "deleted login", "")
	// Mark the second issue soft-deleted directly via SQL — Task 5 ships
	// SoftDeleteIssue but this test runs before that, and the DB-layer
	// behavior we want to verify is "search query filters deleted_at IS NULL".
	_, err := d.ExecContext(ctx,
		`UPDATE issues SET deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = ?`,
		gone.ID)
	require.NoError(t, err)

	got, err := d.SearchFTS(ctx, p.ID, "login", 20, false)
	require.NoError(t, err)
	require.Len(t, got, 1)
	assert.Equal(t, keep.ID, got[0].Issue.ID, "soft-deleted issue must be filtered")

	// includeDeleted=true returns both.
	got, err = d.SearchFTS(ctx, p.ID, "login", 20, true)
	require.NoError(t, err)
	assert.Len(t, got, 2)
}

func TestSearchFTS_EmptyQueryReturnsEmpty(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	createTesterIssueWithBody(ctx, t, d, p.ID, "anything", "")

	got, err := d.SearchFTS(ctx, p.ID, "   ", 20, false)
	require.NoError(t, err)
	assert.Empty(t, got, "blank query → empty result, not an error")
}

func TestSearchFTS_LimitCappedAt200(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	// Create 250 matching issues. The cap must clamp the result set to 200
	// regardless of how large a limit the caller passes; without the cap, this
	// test would return 250 and fail.
	for i := 0; i < 250; i++ {
		createTesterIssueWithBody(ctx, t, d, p.ID, "login bug", "")
	}
	got, err := d.SearchFTS(ctx, p.ID, "login", 1_000_000, false)
	require.NoError(t, err)
	assert.Len(t, got, 200, "limit must be capped at 200")
}

func TestSearchFTS_MultiTermImplicitAND(t *testing.T) {
	// Multi-term queries split on whitespace and AND the terms. "login Safari"
	// must match an issue that contains both terms even when they aren't
	// adjacent — the previous single-phrase wrap missed this.
	d, ctx, p := setupTestProject(t)

	createTesterIssue(ctx, t, d, p.ID, "fix login crash on Safari")
	createTesterIssueWithBody(ctx, t, d, p.ID, "login bug", "")
	createTesterIssueWithBody(ctx, t, d, p.ID, "Safari preferences", "")

	got, err := d.SearchFTS(ctx, p.ID, "login Safari", 20, false)
	require.NoError(t, err)
	require.Len(t, got, 1, "only the issue containing both terms must match")
	assert.Equal(t, "fix login crash on Safari", got[0].Issue.Title)
}

func TestSearchFTS_QueryEscaping(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	createTesterIssueWithBody(ctx, t, d, p.ID, `fix "login" crash`, "")

	// FTS5 syntax characters must not surface as syntax errors.
	got, err := d.SearchFTS(ctx, p.ID, `"login"`, 20, false)
	require.NoError(t, err)
	assert.Len(t, got, 1)
}

// TestSearchFTS_MatchedIn_CrossColumn pins the matched_in fix from roborev
// 16789: when the query is multi-term implicit-AND and the tokens land in
// different columns (title="login", body="Safari"), the per-column subqueries
// must use OR semantics so each column reports as matched. With the old
// AND-based per-column subqueries this returned matched_in=[].
func TestSearchFTS_MatchedIn_CrossColumn(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	createTesterIssueWithBody(ctx, t, d, p.ID, "login bug", "Safari issue")

	got, err := d.SearchFTS(ctx, p.ID, "login Safari", 20, false)
	require.NoError(t, err)
	require.Len(t, got, 1)
	assert.ElementsMatch(t, []string{"title", "body"}, got[0].MatchedIn)
}

// TestSearchFTS_OperatorWordsAsLiterals pins #23: FTS5 reserved words and
// special characters in the user query must be treated as literal phrase
// content, not as FTS5 syntax. The escaping pass quotes each whitespace-split
// token and doubles embedded quotes, which neutralizes NEAR/OR/AND/NOT and
// the `*` prefix-match marker.
func TestSearchFTS_OperatorWordsAsLiterals(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	createTesterIssueWithBody(ctx, t, d, p.ID, "do NOT merge yet", "blocked OR waiting")
	createTesterIssue(ctx, t, d, p.ID, "merge after review")
	// Seeded so AND/NEAR-as-literals can be exercised: each operator-bearing
	// row pairs with a competitor that has the surrounding tokens but lacks
	// the operator word itself. Under operator semantics ("build" AND
	// "deploy") both rows would match; under correct literal semantics only
	// the row containing the literal operator word matches. The test asserts
	// exactly one match, so a regression that lost the FTS5 phrase-quoting
	// fails here.
	createTesterIssue(ctx, t, d, p.ID, "build AND deploy pipeline")
	createTesterIssue(ctx, t, d, p.ID, "build deploy pipeline")
	createTesterIssue(ctx, t, d, p.ID, "place item NEAR exit")
	createTesterIssue(ctx, t, d, p.ID, "place item by exit")

	cases := []struct {
		name, query, wantTitle string
	}{
		{"NOT as literal", "NOT merge", "do NOT merge yet"},
		{"OR as literal", "blocked OR", "do NOT merge yet"},
		{"AND as literal", "build AND deploy", "build AND deploy pipeline"},
		{"NEAR as literal", "item NEAR exit", "place item NEAR exit"},
		{"star is literal not prefix", "merg*", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := d.SearchFTS(ctx, p.ID, tc.query, 20, false)
			require.NoError(t, err, "query %q must parse without FTS5 syntax error", tc.query)
			if tc.wantTitle == "" {
				assert.Len(t, got, 0, "wildcard must not act as prefix-match")
				return
			}
			require.Len(t, got, 1, "query %q must match exactly one row", tc.query)
			assert.Equal(t, tc.wantTitle, got[0].Issue.Title)
		})
	}
}

// TestSearchFTSAny_FindsNearDuplicates pins the look-alike fix from roborev
// 16791: implicit-AND search misses a row that's a near-duplicate but lacks
// one of the query tokens; the OR variant retrieves it so similarity.Score
// can decide. With AND, "login crash Safari critical" excludes a row that
// only contains "login crash Safari" (no "critical").
func TestSearchFTSAny_FindsNearDuplicates(t *testing.T) {
	d, ctx, p := setupTestProject(t)
	createTesterIssueWithBody(ctx, t, d, p.ID, "login crash on Safari", "stack trace")

	// Implicit-AND: query has an extra token ("critical") that the row lacks
	// — the row is filtered out before similarity scoring would see it.
	gotAnd, err := d.SearchFTS(ctx, p.ID, "login crash Safari critical", 20, false)
	require.NoError(t, err)
	assert.Len(t, gotAnd, 0, "AND form must filter rows missing any token")

	// OR variant: same query, but the row matches because it contains at
	// least one of the tokens. similarity.Score in the handler decides
	// whether to actually treat this as a duplicate.
	gotOr, err := d.SearchFTSAny(ctx, p.ID, "login crash Safari critical", 20, false)
	require.NoError(t, err)
	require.Len(t, gotOr, 1, "OR form must retrieve near-duplicates")
	assert.Equal(t, "login crash on Safari", gotOr[0].Issue.Title)
}

package api_test

import (
	"encoding/json"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/wesm/kata/internal/api"
)

func TestAPIError_StatusAndBodyShape(t *testing.T) {
	err := api.NewError(404, "issue_not_found", "issue #42 does not exist", "kata search", nil)
	assert.Equal(t, 404, err.Status)

	body := err.Envelope()
	assert.Equal(t, "issue_not_found", body.Error.Code)
	assert.Equal(t, "issue #42 does not exist", body.Error.Message)
	assert.Equal(t, "kata search", body.Error.Hint)

	js, err2 := json.Marshal(body)
	require.NoError(t, err2)
	assert.Contains(t, string(js), `"code":"issue_not_found"`)
}

func TestAPIError_DataPropagates(t *testing.T) {
	err := api.NewError(409, "duplicate_candidates", "x", "", map[string]any{
		"candidates": []int{1, 2},
	})
	body := err.Envelope()
	assert.Equal(t, []int{1, 2}, body.Error.Data["candidates"])
}

package db_test

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/wesm/kata/internal/db"
	"github.com/wesm/kata/internal/uid"
)

func TestFingerprint_DeterministicOverInputOrder(t *testing.T) {
	owner := "alice"
	a := db.Fingerprint("fix login", "details", &owner,
		[]string{"bug", "ui"},
		[]db.InitialLink{{Type: "blocks", ToNumber: 7}, {Type: "parent", ToNumber: 3}}, nil)
	b := db.Fingerprint("fix login", "details", &owner,
		[]string{"ui", "bug"}, // labels reordered
		[]db.InitialLink{{Type: "parent", ToNumber: 3}, {Type: "blocks", ToNumber: 7}}, nil) // links reordered
	assert.Equal(t, a, b, "fingerprint must be order-independent for labels and links")
}

func TestFingerprint_CanonicalizesWhitespace(t *testing.T) {
	a := db.Fingerprint("fix login", "body text", nil, nil, nil, nil)
	b := db.Fingerprint("  fix\t\n  login  ", "body  text", nil, nil, nil, nil)
	assert.Equal(t, a, b, "internal whitespace runs and trimming must collapse")
}

func TestFingerprint_DiffersOnDifferentInputs(t *testing.T) {
	base := db.Fingerprint("a", "b", nil, nil, nil, nil)
	priority := int64(1)
	cases := []struct {
		name        string
		fingerprint string
	}{
		{"different_title", db.Fingerprint("aa", "b", nil, nil, nil, nil)},
		{"different_body", db.Fingerprint("a", "bb", nil, nil, nil, nil)},
		{"different_owner", db.Fingerprint("a", "b", strPtr("x"), nil, nil, nil)},
		{"different_labels", db.Fingerprint("a", "b", nil, []string{"bug"}, nil, nil)},
		{"different_links", db.Fingerprint("a", "b", nil, nil,
			[]db.InitialLink{{Type: "blocks", ToNumber: 1}}, nil)},
		{"different_priority", db.Fingerprint("a", "b", nil, nil, nil, &priority)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			assert.NotEqual(t, base, tc.fingerprint)
		})
	}
}

func TestFingerprint_CaseSensitive(t *testing.T) {
	// Spec §3.6: canonical() does NOT lowercase. Title casing matters.
	a := db.Fingerprint("Fix Login", "", nil, nil, nil, nil)
	b := db.Fingerprint("fix login", "", nil, nil, nil, nil)
	assert.NotEqual(t, a, b)
}

func TestFingerprint_NilAndEmptyOwnerAreEquivalent(t *testing.T) {
	empty := ""
	a := db.Fingerprint("a", "b", nil, nil, nil, nil)
	b := db.Fingerprint("a", "b", &empty, nil, nil, nil)
	assert.Equal(t, a, b, "nil owner and empty owner produce the same fingerprint")
}

func TestFingerprint_HexLowercaseSHA256(t *testing.T) {
	got := db.Fingerprint("a", "b", nil, nil, nil, nil)
	assert.Len(t, got, 64, "sha256 hex is 64 chars")
	assert.True(t, strings.ToLower(got) == got, "must be lowercase hex")
}

// TestFingerprint_Vector pins exact hex outputs so any change to the canonical
// byte layout, separator order, JSON shape, sort order, or Canonical()
// behavior immediately breaks the test. This is the cross-language contract.
func TestFingerprint_Vector(t *testing.T) {
	// All-empty inputs: title=\nbody=\nowner=\nlabels=\nlinks=[]
	// Nil priority MUST omit the priority line so this hash matches the
	// pre-priority five-line fingerprint shape — existing idempotency events
	// in older databases continue to match.
	assert.Equal(t,
		"3e3678620b59364a3d56c8608ff431933b042a8619e74892243b0d2bfdb09af2",
		db.Fingerprint("", "", nil, nil, nil, nil),
		"empty-everything fingerprint must not drift")

	// Filled: one label, one parent link.
	assert.Equal(t,
		"2c77531b9b3e7522ccf86eb353fc2aaa8cd8418e1132c8ebb1f2f80ea1dca8db",
		db.Fingerprint("hello", "world", nil, []string{"bug"},
			[]db.InitialLink{{Type: "parent", ToNumber: 3}}, nil),
		"filled fingerprint must not drift")
}

// TestFingerprint_PriorityNilPreservesLegacyShape locks the rule that nil
// priority emits the same canonical bytes as the pre-priority signature, so
// existing fingerprints stored in databases keep matching after the upgrade.
func TestFingerprint_PriorityNilPreservesLegacyShape(t *testing.T) {
	// Same hash whether priority is nil or omitted entirely.
	a := db.Fingerprint("a", "b", nil, []string{"bug"},
		[]db.InitialLink{{Type: "parent", ToNumber: 3}}, nil)
	b := db.Fingerprint("a", "b", nil, []string{"bug"},
		[]db.InitialLink{{Type: "parent", ToNumber: 3}}, nil)
	assert.Equal(t, a, b)

	// Setting any priority diverges from the nil-priority hash.
	zero := int64(0)
	withZero := db.Fingerprint("a", "b", nil, []string{"bug"},
		[]db.InitialLink{{Type: "parent", ToNumber: 3}}, &zero)
	assert.NotEqual(t, a, withZero,
		"P0 differs from nil priority — they are not the same identity")
}

