// TestLookupIdempotency_OnlyIssueCreatedEvents ensures that an idempotency_key
// in the payload of a non-issue.created event (e.g. issue.edited) is never
// returned. The partial index already enforces this; the SQL WHERE clause
// reinforces it. This test locks both layers.
func TestLookupIdempotency_OnlyIssueCreatedEvents(t *testing.T) {
	d, ctx, p, issue := setupTestIssue(t)
	// Stamp the idempotency_key onto a NON-issue.created row by inserting a
	// fake issue.edited event. The partial index excludes this row by type;
	// the WHERE e.type = 'issue.created' clause reinforces.
	eventUID, err := uid.New()
	require.NoError(t, err)
	_, err = d.ExecContext(ctx, `
		INSERT INTO events (uid, origin_instance_uid, project_id, project_identity, issue_id, issue_number, type, actor, payload, created_at)
		VALUES (?, (SELECT value FROM meta WHERE key='instance_uid'), ?, ?, ?, ?, 'issue.edited', 'tester',
		        json_object('idempotency_key', 'K1', 'idempotency_fingerprint', 'fp'),
		        strftime('%Y-%m-%dT%H:%M:%fZ','now'))`,
		eventUID, p.ID, p.Identity, issue.ID, issue.Number)
	require.NoError(t, err)

	got, err := d.LookupIdempotency(ctx, p.ID, "K1", time.Now().Add(-1*time.Hour))
	require.NoError(t, err)
	assert.Nil(t, got, "non-issue.created event with same key must not match")
}

package tui

import "testing"

// setupSeededCache returns a cache pre-populated with one issue for the
// canonical test project, plus the key used to seed it.
func setupSeededCache() (*issueCache, cacheKey) {
	c := newIssueCache()
	k := cacheKey{projectID: 7}
	c.put(k, []Issue{{Number: 1}})
	return c, k
}

func assertStale(t *testing.T, c *issueCache, want bool) {
	t.Helper()
	if got := c.isStale(); got != want {
		t.Fatalf("isStale = %v, want %v", got, want)
	}
}

// TestCache_PutThenStaleThenRefetch covers the steady-state SSE flow:
// fetch populates the slot, an event marks it stale, and a fresh fetch
// clears stale and replaces the data.
func TestCache_PutThenStaleThenRefetch(t *testing.T) {
	c, k := setupSeededCache()
	assertStale(t, c, false)
	c.markStale()
	assertStale(t, c, true)
	c.put(k, []Issue{{Number: 2}})
	assertStale(t, c, false)
	if len(c.data) != 1 || c.data[0].Number != 2 {
		t.Fatalf("data = %+v, want [{Number:2}]", c.data)
	}
}

// TestCache_DropEmpties confirms drop() leaves the slot empty so a
// follow-up isStale returns false (no slot, nothing to be stale about).
// This is the sync.reset_required path.
func TestCache_DropEmpties(t *testing.T) {
	c, _ := setupSeededCache()
	c.markStale()
	c.drop()
	assertStale(t, c, false)
	if c.set {
		t.Fatal("after drop, set must be false")
	}
	if len(c.data) != 0 {
		t.Fatalf("after drop, data must be empty, got %+v", c.data)
	}
}

// TestCache_MarkStaleIdempotent: multiple events in a 150ms window all
// flip stale; the second markStale on an already-stale cache is a no-op.
func TestCache_MarkStaleIdempotent(t *testing.T) {
	c, _ := setupSeededCache()
	c.markStale()
	c.markStale()
	c.markStale()
	assertStale(t, c, true)
}

func TestCache_RenderFilterDoesNotChangeSlotKey(t *testing.T) {
	m := Model{
		scope: scope{projectID: 7},
		list: listModel{filter: ListFilter{
			Status: "open", Owner: "alice", Search: "bug", Labels: []string{"prio-1"},
		}},
	}
	want := cacheKey{projectID: 7, limit: queueFetchLimit}
	if !cacheKeysEqual(m.currentCacheKey(), want) {
		t.Fatalf("currentCacheKey = %+v, want %+v", m.currentCacheKey(), want)
	}
}

// TestCache_EmptyIsNotStale: a freshly constructed cache is not stale —
// stale=true requires a real slot to be stale about.
func TestCache_EmptyIsNotStale(t *testing.T) {
	c := newIssueCache()
	assertStale(t, c, false)
}

package tui

import (
	"context"
	"testing"
)

// buildModelWithLabelCache returns a minimal Model with the label-
// cache state initialized. api is nil because the dispatch + acceptance
// tests inspect cache state, not Cmd execution — fetchLabelsCmd's
// nil-api branch returns a synthetic message that doesn't reach the
// network.
func buildModelWithLabelCache(_ *testing.T) Model {
	return Model{
		view:          viewList,
		projectLabels: newLabelCache(),
	}
}

// setupScopedModel returns a label-cache-initialized Model with the
// active project scope set to pid — the shared starting state for
// every dispatch/acceptance test in this file.
func setupScopedModel(t *testing.T, pid int64) Model {
	m := buildModelWithLabelCache(t)
	m.scope = scope{projectID: pid}
	return m
}

// fakeLabelLister is a labelLister stub that returns a canned slice
// without touching the network. Used by the race-fix coverage so the
// test exercises the rejection path with a real (non-empty) response,
// not the nil-api synthetic-empty fallback.
type fakeLabelLister struct {
	labels []LabelCount
	err    error
	calls  int
}

func (f *fakeLabelLister) ListLabels(_ context.Context, _ int64) ([]LabelCount, error) {
	f.calls++
	return f.labels, f.err
}

// TestLabelCache_DispatchStampsGenBeforeResponse pins the load-bearing
// invariant: dispatchLabelFetch must stamp a fresh gen on the cache
// entry BEFORE the HTTP request goes out. The race the fix prevents:
// dispatch1 (gen=1) → dispatch2 (gen=2) → cmd1 runs and returns
// labelsFetchedMsg{gen=1} → handler must drop it because the entry's
// gen has been bumped to 2.
//
// This test exercises that race end-to-end: it captures the FIRST
// cmd, fires a SECOND dispatch (which bumps cache.gen to 2), runs the
// first cmd against a fake api that returns real labels, and asserts
// the resulting gen=1 message is rejected. A regression that moved
// the gen-stamp into the cmd (or dropped the gen check in the
// handler) would let the stale labels overwrite the cache.
func TestLabelCache_DispatchStampsGenBeforeResponse(t *testing.T) {
	pid := int64(7)
	m := setupScopedModel(t, pid)
	fake := &fakeLabelLister{labels: []LabelCount{{Label: "from-first", Count: 1}}}
	// First dispatch — gen stamped to 1, fetching=true. Capture the
	// cmd; do NOT run it yet so the second dispatch can bump gen.
	m, _ = m.dispatchLabelFetch(pid)
	if got := m.projectLabels.byProject[pid].gen; got != 1 {
		t.Fatalf("first dispatch gen = %d, want 1", got)
	}
	// Build the cmd the way dispatchLabelFetch would have, but with
	// the fake lister so it returns real labels rather than nil-api
	// synthetic empties — this is what makes the rejection meaningful.
	firstCmd := fetchLabelsCmd(fake, pid, 1)
	// Second dispatch — bumps cache.gen to 2 BEFORE firstCmd runs.
	m, _ = m.dispatchLabelFetch(pid)
	if got := m.projectLabels.byProject[pid].gen; got != 2 {
		t.Fatalf("second dispatch gen = %d, want 2 (must bump even "+
			"though first cmd hasn't run)", got)
	}
	// Now run the first cmd — it produces labelsFetchedMsg{gen: 1, ...}.
	msg := firstCmd()
	nm, _ := updateModel(m, msg)
	entry := nm.projectLabels.byProject[pid]
	if len(entry.labels) != 0 {
		t.Fatalf("stale gen=1 response must be rejected because "+
			"cache.gen=2; got labels=%v", entry.labels)
	}
	if fake.calls != 1 {
		t.Fatalf("fake.ListLabels calls = %d, want 1", fake.calls)
	}
}

// TestLabelCache_StaleGenResponseDropped: a response whose gen lags
// behind the cache's current gen must NOT populate the cache. The
// acceptance check on response is gen >= cache.gen; older messages
// are silently discarded so a slow first-dispatch can't overwrite a
// freshly-invalidated cache entry.
func TestLabelCache_StaleGenResponseDropped(t *testing.T) {
	pid := int64(7)
	m := setupScopedModel(t, pid)
	m, _ = m.dispatchLabelFetch(pid) // gen=1
	m, _ = m.dispatchLabelFetch(pid) // gen=2 (newer)
	nm, _ := updateModel(m, labelsFetchedMsg{
		pid: pid, gen: 1, labels: []LabelCount{{Label: "old", Count: 1}},
	})
	entry := nm.projectLabels.byProject[pid]
	if len(entry.labels) != 0 {
		t.Fatalf("stale gen=1 response must NOT populate cache "+
			"(cache.gen=2); got labels=%v", entry.labels)
	}
}

// TestLabelCache_InactiveProjectResponseStillPopulatesCache:
// a response for an inactive project (msg.pid != targetPID()) MUST
// still populate the per-project cache entry. The cache is keyed by
// pid, so populating an inactive project's entry is harmless — and
// dropping the response (the prior contract) left entry.fetching=true
// forever, so when the user later returned to the original project
// dispatchLabelFetchIfNeeded would see "entry exists" and skip the
// re-fetch, leaving the suggestion menu stuck in "loading…" forever
// (jobs 240/241).
//
// Setup: dispatch for pid=7 (creates entry, fetching=true), switch
// scope to pid=8, then send the pid=7 response. Assert the pid=7
// entry IS populated AND fetching=false — that's the new contract.
func TestLabelCache_InactiveProjectResponseStillPopulatesCache(t *testing.T) {
	m := setupScopedModel(t, 7) // active project is 7
	// Dispatch creates the entry for pid=7 with gen=1, fetching=true.
	m, _ = m.dispatchLabelFetch(7)
	// User switches project to pid=8 BEFORE the response lands.
	m.scope = scope{projectID: 8}
	// Response for pid=7 arrives from the now-inactive fetch. The
	// per-project cache must accept it — the entry's pid matches the
	// message's pid, so the data goes in the right slot.
	nm, _ := updateModel(m, labelsFetchedMsg{
		pid: 7, gen: 1,
		labels: []LabelCount{{Label: "from7", Count: 1}},
	})
	entry := nm.projectLabels.byProject[7]
	if len(entry.labels) != 1 || entry.labels[0].Label != "from7" {
		t.Fatalf("response for pid=7 must populate the pid=7 cache "+
			"entry even when target is pid=8 (cache is per-project); "+
			"got labels=%v", entry.labels)
	}
	if entry.fetching {
		t.Fatal("entry.fetching must be false after the response is " +
			"accepted; otherwise dispatchLabelFetchIfNeeded skips a " +
			"future re-fetch and the suggestion menu stays stuck in " +
			"loading… forever (jobs 240/241)")
	}
}

// TestBatchLabelRefresh_GatesOnCacheExistence pins I1: a successful
// label.add mutation against a project the user has NEVER opened the
// `+` menu for (no cache entry yet) must NOT trigger a wasted
// ListLabels fetch. Mirrors maybeRefetchLabels's SSE gate so the two
// invalidation paths behave identically.
func TestBatchLabelRefresh_GatesOnCacheExistence(t *testing.T) {
	m := setupScopedModel(t, 7)
	// No cache entry for pid=7 — the user never opened the menu.
	mut := mutationDoneMsg{
		kind: "label.add",
		resp: &MutationResp{Issue: &Issue{ProjectID: 7, Number: 42}},
	}
	out, cmd := batchLabelRefresh(m, nil, mut)
	nm := out.(Model)
	if cmd != nil {
		t.Fatal("batchLabelRefresh must not dispatch when the project " +
			"has no cache entry — wastes a ListLabels HTTP roundtrip")
	}
	if _, exists := nm.projectLabels.byProject[7]; exists {
		t.Fatal("batchLabelRefresh must not create a cache entry " +
			"for an unopened project")
	}
}

// TestBatchLabelRefresh_DispatchesWhenEntryExists: the complement of
// the gate test — when a cache entry IS present (the user has hit `+`
// against the project at least once), a successful label mutation
// MUST dispatch a refresh so the menu's count column stays accurate.
func TestBatchLabelRefresh_DispatchesWhenEntryExists(t *testing.T) {
	m := setupScopedModel(t, 7)
	// Prime an entry as if the user had previously opened the menu.
	m.projectLabels.byProject[7] = labelCacheEntry{
		pid: 7, gen: 1,
		labels: []LabelCount{{Label: "bug", Count: 2}},
	}
	mut := mutationDoneMsg{
		kind: "label.add",
		resp: &MutationResp{Issue: &Issue{ProjectID: 7, Number: 42}},
	}
	out, cmd := batchLabelRefresh(m, nil, mut)
	nm := out.(Model)
	if cmd == nil {
		t.Fatal("batchLabelRefresh must dispatch when the project has " +
			"an existing cache entry")
	}
	if !nm.projectLabels.byProject[7].fetching {
		t.Fatal("dispatched entry must be fetching=true")
	}
}

// TestMutAffectsLabelCounts_AllRelevantKinds pins which mutation
// kinds invalidate the per-project label aggregate. Plan 8 commit 4
// extended the set to include "create" because the multi-field
// new-issue form can attach Labels at create time. The cache refresh
// is still gated against per-project entry existence in
// batchLabelRefresh, so a create against a project the user never
// opened the menu for remains a zero-cost no-op.
func TestMutAffectsLabelCounts_AllRelevantKinds(t *testing.T) {
	if !mutAffectsLabelCounts(mutationDoneMsg{kind: "create"}) {
		t.Fatal("'create' must trigger a label-aggregate refetch " +
			"(commit 4 form may attach labels)")
	}
	if !mutAffectsLabelCounts(mutationDoneMsg{kind: "label.add"}) {
		t.Fatal("'label.add' must trigger a label-aggregate refetch")
	}
	if !mutAffectsLabelCounts(mutationDoneMsg{kind: "label.remove"}) {
		t.Fatal("'label.remove' must trigger a label-aggregate refetch")
	}
	// Errors short-circuit regardless of kind.
	if mutAffectsLabelCounts(mutationDoneMsg{kind: "create", err: errStub("boom")}) {
		t.Fatal("error must short-circuit refetch")
	}
}

// TestLabelCache_SSEEventInvalidatesSuggestionCacheOnly: an
// issue.labeled SSE event for a project that has a cache entry must
// trigger a refetch (entry.fetching=true, entry.gen advanced). The
// list/detail refetch path is independent — this test asserts the
// suggestion-cache invalidation specifically.
func TestLabelCache_SSEEventInvalidatesSuggestionCacheOnly(t *testing.T) {
	pid := int64(7)
	m := setupScopedModel(t, pid)
	m.cache = newIssueCache()
	m.sseCh = nil // no SSE bridge to re-arm
	m.nextLabelsGen = 5
	m.projectLabels.byProject[pid] = labelCacheEntry{
		labels: []LabelCount{{Label: "stale", Count: 1}},
		gen:    5, pid: pid,
	}
	nm, _ := updateModel(m, eventReceivedMsg{
		eventType: "issue.labeled", projectID: pid, issueNumber: 42,
	})
	entry := nm.projectLabels.byProject[pid]
	if !entry.fetching {
		t.Fatal("SSE event must trigger refetch (fetching=true)")
	}
	if entry.gen <= 5 {
		t.Fatalf("gen must advance past 5; got %d", entry.gen)
	}
}

package db

import (
	"context"
	"errors"
	"fmt"
	"testing"
	"time"

	backoff "github.com/cenkalti/backoff/v5"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	sqlite3 "modernc.org/sqlite/lib"
)

type codedSQLiteErr int

func (e codedSQLiteErr) Error() string { return "sqlite error" }
func (e codedSQLiteErr) Code() int     { return int(e) }

func TestIsLockContentionRecognizesSQLiteBusyAndLocked(t *testing.T) {
	assert.True(t, IsLockContention(codedSQLiteErr(sqlite3.SQLITE_BUSY)))
	assert.True(t, IsLockContention(codedSQLiteErr(sqlite3.SQLITE_LOCKED)))
	assert.True(t, IsLockContention(fmt.Errorf("wrapped: %w",
		codedSQLiteErr(sqlite3.SQLITE_LOCKED|(1<<8)))))
	assert.False(t, IsLockContention(codedSQLiteErr(sqlite3.SQLITE_CONSTRAINT)))
	assert.False(t, IsLockContention(errors.New("database is locked")))
}

func TestRetryLockContentionRetriesLockContentionUntilSuccess(t *testing.T) {
	attempts := 0

	err := retryLockContention(context.Background(), lockRetryConfig{
		maxElapsed: time.Second,
		newBackOff: func() backoff.BackOff {
			return &backoff.ZeroBackOff{}
		},
	}, func() error {
		attempts++
		if attempts < 4 {
			return fmt.Errorf("reopen: %w", codedSQLiteErr(sqlite3.SQLITE_LOCKED))
		}
		return nil
	})

	require.NoError(t, err)
	assert.Equal(t, 4, attempts)
}

func TestRetryLockContentionDoesNotRetryOtherErrors(t *testing.T) {
	wantErr := errors.New("constraint failed")
	attempts := 0

	err := retryLockContention(context.Background(), lockRetryConfig{
		maxElapsed: time.Second,
		newBackOff: func() backoff.BackOff {
			return &backoff.ZeroBackOff{}
		},
	}, func() error {
		attempts++
		return wantErr
	})

	assert.ErrorIs(t, err, wantErr)
	assert.Equal(t, 1, attempts)
}

func TestNewLockBackOffUsesSmallJitteredPolicy(t *testing.T) {
	got, ok := newLockBackOff().(*lockBackOff)
	require.True(t, ok)
	inner, ok := got.inner.(*backoff.ExponentialBackOff)
	require.True(t, ok)

	assert.Equal(t, time.Millisecond, inner.InitialInterval)
	assert.Equal(t, time.Second, inner.MaxInterval)
	assert.Equal(t, 2.0, inner.Multiplier)
	assert.Equal(t, 0.5, inner.RandomizationFactor)
	assert.Equal(t, time.Second, got.max)
}

func TestLockBackOffCapsRandomizedDelayAtOneSecond(t *testing.T) {
	bo := &lockBackOff{
		inner: &sequenceBackOff{next: []time.Duration{
			2 * time.Second,
		}},
		max: time.Second,
	}

	assert.Equal(t, time.Second, bo.NextBackOff())
}

type sequenceBackOff struct {
	next []time.Duration
}

func (b *sequenceBackOff) NextBackOff() time.Duration {
	if len(b.next) == 0 {
		return backoff.Stop
	}
	d := b.next[0]
	b.next = b.next[1:]
	return d
}

func (b *sequenceBackOff) Reset() {}

package daemon

import (
	"context"

	"github.com/danielgtaylor/huma/v2"

	"github.com/wesm/kata/internal/api"
	"github.com/wesm/kata/internal/db"
)

// registerActionsHandlers installs POST /actions/close and /actions/reopen.
// CloseIssue and ReopenIssue return changed=false with a nil event when the
// issue is already in the target state; both fields propagate verbatim into
// the MutationResponse envelope.
func registerActionsHandlers(humaAPI huma.API, cfg ServerConfig) {
	huma.Register(humaAPI, huma.Operation{
		OperationID: "closeIssue",
		Method:      "POST",
		Path:        "/api/v1/projects/{project_id}/issues/{number}/actions/close",
	}, func(ctx context.Context, in *api.ActionRequest) (*api.MutationResponse, error) {
		if err := validateActor(in.Body.Actor); err != nil {
			return nil, err
		}
		issue, err := activeIssueByNumber(ctx, cfg.DB, in.ProjectID, in.Number)
		if err != nil {
			return nil, err
		}
		var updated db.Issue
		var evt *db.Event
		var changed bool
		err = db.RetryLockContention(ctx, func() error {
			var err error
			updated, evt, changed, err = cfg.DB.CloseIssue(ctx, issue.ID, in.Body.Reason, in.Body.Actor)
			return err
		})
		if err != nil {
			return nil, api.NewError(500, "internal", err.Error(), "", nil)
		}
		if changed && evt != nil {
			cfg.Broadcaster.Broadcast(StreamMsg{Kind: "event", Event: evt, ProjectID: in.ProjectID})
			cfg.Hooks.Enqueue(*evt)
		}
		out := &api.MutationResponse{}
		out.Body.Issue = updated
		out.Body.Event = evt
		out.Body.Changed = changed
		return out, nil
	})

	huma.Register(humaAPI, huma.Operation{
		OperationID: "reopenIssue",
		Method:      "POST",
		Path:        "/api/v1/projects/{project_id}/issues/{number}/actions/reopen",
	}, func(ctx context.Context, in *api.ActionRequest) (*api.MutationResponse, error) {
		if err := validateActor(in.Body.Actor); err != nil {
			return nil, err
		}
		issue, err := activeIssueByNumber(ctx, cfg.DB, in.ProjectID, in.Number)
		if err != nil {
			return nil, err
		}
		var updated db.Issue
		var evt *db.Event
		var changed bool
		err = db.RetryLockContention(ctx, func() error {
			var err error
			updated, evt, changed, err = cfg.DB.ReopenIssue(ctx, issue.ID, in.Body.Actor)
			return err
		})
		if err != nil {
			return nil, api.NewError(500, "internal", err.Error(), "", nil)
		}
		if changed && evt != nil {
			cfg.Broadcaster.Broadcast(StreamMsg{Kind: "event", Event: evt, ProjectID: in.ProjectID})
			cfg.Hooks.Enqueue(*evt)
		}
		out := &api.MutationResponse{}
		out.Body.Issue = updated
		out.Body.Event = evt
		out.Body.Changed = changed
		return out, nil
	})
}

// Package api types for Plan 4 events endpoints. EventEnvelope is the JSON
// shape carried in SSE data: lines and the events array of PollEventsResponse;
// it mirrors db.Event one-for-one but lives in api so the wire schema stays
// independent of internal storage shape.
package api //nolint:revive // package name "api" is fixed by Plan 1 §4 wire-types layout.

import (
	"encoding/json"
	"reflect"
	"time"

	"github.com/danielgtaylor/huma/v2"
)

// OptionalInt is a Huma-compatible query param wrapper for optional integers.
// It tracks whether the param was explicitly set (as opposed to absent/zero).
// Implements huma.SchemaProvider (schema appears as integer), huma.ParamWrapper
// (Huma parses into Value), and huma.ParamReactor (records whether provided).
type OptionalInt struct {
	Value int
	IsSet bool
}

// Schema implements huma.SchemaProvider so the OpenAPI schema is "integer"
// rather than the default struct schema.
func (OptionalInt) Schema(r huma.Registry) *huma.Schema {
	return huma.SchemaFromType(r, reflect.TypeOf(0))
}

// Receiver returns the reflect.Value of the int field for Huma to parse into.
func (o *OptionalInt) Receiver() reflect.Value {
	return reflect.ValueOf(o).Elem().Field(0)
}

// OnParamSet records whether the query param was present in the request.
func (o *OptionalInt) OnParamSet(isSet bool, _ any) {
	o.IsSet = isSet
}

// EventEnvelope is the wire shape for a single event row.
type EventEnvelope struct {
	EventID           int64   `json:"event_id"`
	EventUID          string  `json:"event_uid"`
	OriginInstanceUID string  `json:"origin_instance_uid"`
	Type              string  `json:"type"`
	ProjectID         int64   `json:"project_id"`
	ProjectUID        string  `json:"project_uid"`
	ProjectIdentity   string  `json:"project_identity"`
	IssueID           *int64  `json:"issue_id,omitempty"`
	IssueUID          *string `json:"issue_uid,omitempty"`
	IssueNumber       *int64  `json:"issue_number,omitempty"`
	RelatedIssueID    *int64  `json:"related_issue_id,omitempty"`
	RelatedIssueUID   *string `json:"related_issue_uid,omitempty"`
	Actor             string  `json:"actor"`
	// Payload is the event-type-specific JSON object. Always valid JSON
	// because the schema enforces json_valid(payload) at write time.
	Payload   json.RawMessage `json:"payload,omitempty"`
	CreatedAt time.Time       `json:"created_at"`
}

// EventReset is the data: payload of a sync.reset_required SSE frame and the
// stripped-down content of a poll response when the cursor falls inside a
// purge gap.
type EventReset struct {
	EventID      int64 `json:"event_id"`       // == ResetAfterID; mirrors the SSE id: line.
	ResetAfterID int64 `json:"reset_after_id"` // minimum safe resume cursor.
}

// PollEventsRequest is GET /api/v1/projects/{project_id}/events (per-project).
// AfterID is exclusive; the response's NextAfterID is the cursor the client
// should pass on the next request. Limit defaults to 100 and is clamped to
// 1000 server-side; explicit zero or negative Limit returns 400 validation.
type PollEventsRequest struct {
	ProjectID int64       `path:"project_id"`
	AfterID   int64       `query:"after_id,omitempty"`
	Limit     OptionalInt `query:"limit,omitempty"`
}

// PollEventsGlobalRequest is GET /api/v1/events (cross-project). Same semantics
// as PollEventsRequest but without the path-level project_id, which Huma
// marks required and would reject requests to the global endpoint.
type PollEventsGlobalRequest struct {
	AfterID int64       `query:"after_id,omitempty"`
	Limit   OptionalInt `query:"limit,omitempty"`
}

// PollEventsResponse is the response for both polling endpoints. ResetRequired
// signals a purge-invalidated cursor; when true, Events is empty and the
// client should refetch state and resume from ResetAfterID.
type PollEventsResponse struct {
	Body struct {
		ResetRequired bool            `json:"reset_required"`
		ResetAfterID  int64           `json:"reset_after_id,omitempty"`
		Events        []EventEnvelope `json:"events"`        // always non-nil; empty array on no rows
		NextAfterID   int64           `json:"next_after_id"` // = max events.id in response, or after_id if empty
	}
}

//nolint:revive // api is the public package namespace used throughout the repo.
package api

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"

	"github.com/danielgtaylor/huma/v2"
)

// ErrorBody is the inner payload of an error envelope.
type ErrorBody struct {
	Code    string         `json:"code"`
	Message string         `json:"message"`
	Hint    string         `json:"hint,omitempty"`
	Data    map[string]any `json:"data,omitempty"`
}

// ErrorEnvelope is the stable wire shape for non-2xx responses.
type ErrorEnvelope struct {
	Status int       `json:"status"`
	Error  ErrorBody `json:"error"`
}

// APIError is the Go representation that handlers return; satisfies Huma's
// StatusError interface so the framework serializes the envelope verbatim.
// Plan 1 §4.6 fixes the public name as APIError; renaming would break the
// documented wire contract and CLI parser.
//
//nolint:revive // see comment above re: fixed Plan 1 §4.6 public name.
type APIError struct {
	Status  int
	Code    string
	Message string
	Hint    string
	Data    map[string]any
}

// NewError constructs an APIError. Hint and data are optional.
func NewError(status int, code, message, hint string, data map[string]any) *APIError {
	return &APIError{Status: status, Code: code, Message: message, Hint: hint, Data: data}
}

// Error implements the standard error interface.
func (e *APIError) Error() string {
	return fmt.Sprintf("%d %s: %s", e.Status, e.Code, e.Message)
}

// GetStatus implements huma.StatusError so the framework picks the right code.
func (e *APIError) GetStatus() int { return e.Status }

// Envelope returns the JSON body shape used in responses.
func (e *APIError) Envelope() ErrorEnvelope {
	return ErrorEnvelope{
		Status: e.Status,
		Error: ErrorBody{
			Code:    e.Code,
			Message: e.Message,
			Hint:    e.Hint,
			Data:    e.Data,
		},
	}
}

// MarshalJSON serializes the envelope so Huma's default response writer emits
// our wire shape rather than the framework default.
func (e *APIError) MarshalJSON() ([]byte, error) {
	return json.Marshal(e.Envelope())
}

// InstallErrorFormatter wires Huma so non-API-typed errors (panics, validation
// failures) also serialize to ErrorEnvelope. Call once at server startup.
// Huma emits 422 for request-body validation failures; we normalize that to
// 400 with code "validation" so the wire contract documented in spec §4.7
// (no 422 in the status table) holds.
//
// Validation errors arrive with a generic message ("validation failed") plus
// a slice of huma.ErrorDetail entries that carry the per-field details.
// Without folding the details into the message, both human ("kata: validation
// failed") and JSON envelope payloads tell the user nothing about what went
// wrong (hammer-test finding #11). Fold up to ~3 details into the surfaced
// message in "field: reason" form so close --reason banana, link 3 banana 4,
// and list --status nonsense surface actionable feedback.
func InstallErrorFormatter() {
	huma.NewError = func(status int, message string, errs ...error) huma.StatusError {
		if status == http.StatusUnprocessableEntity {
			status = http.StatusBadRequest
		}
		return &APIError{
			Status:  status,
			Code:    codeForStatus(status),
			Message: foldDetailsIntoMessage(message, errs),
		}
	}
}

// foldDetailsIntoMessage appends per-error detail to the generic huma
// validation message. Caps at 3 details so a request with many invalid
// fields doesn't produce a multi-paragraph error string; an "and N more"
// suffix replaces the truncated tail.
func foldDetailsIntoMessage(message string, errs []error) string {
	if len(errs) == 0 {
		return message
	}
	const maxDetails = 3
	parts := make([]string, 0, maxDetails)
	for i, e := range errs {
		if i == maxDetails {
			parts = append(parts, fmt.Sprintf("(and %d more)", len(errs)-maxDetails))
			break
		}
		parts = append(parts, formatErrorDetail(e))
	}
	return message + ": " + strings.Join(parts, "; ")
}

// formatErrorDetail extracts a "location: message" pair from an
// ErrorDetailer when possible; falls back to the error's own string.
// huma's validator sets Location for body/path/query field violations
// so the user can tell which field failed.
func formatErrorDetail(e error) string {
	if d, ok := e.(huma.ErrorDetailer); ok {
		det := d.ErrorDetail()
		if det != nil {
			loc := strings.TrimPrefix(det.Location, "body.")
			loc = strings.TrimPrefix(loc, "query.")
			loc = strings.TrimPrefix(loc, "path.")
			if loc != "" {
				return loc + ": " + det.Message
			}
			return det.Message
		}
	}
	return e.Error()
}

func codeForStatus(status int) string {
	switch status {
	case http.StatusBadRequest, http.StatusUnprocessableEntity:
		return "validation"
	case http.StatusNotFound:
		return "not_found"
	case http.StatusConflict:
		return "conflict"
	case http.StatusPreconditionFailed:
		return "confirm_required"
	case http.StatusInternalServerError:
		return "internal"
	default:
		return "error"
	}
}

// WriteEnvelope writes an ErrorEnvelope JSON body with the given status code
// and Content-Type: application/json. Used by HTTP middleware that needs to
// emit the same wire shape as handler-returned APIErrors.
func WriteEnvelope(w http.ResponseWriter, status int, code, message string) {
	body, _ := json.Marshal(ErrorEnvelope{
		Status: status,
		Error:  ErrorBody{Code: code, Message: message},
	})
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(body)
}

// EnsureCancelled is a small helper so handlers can early-return when ctx is
// cancelled without producing a 500 envelope.
func EnsureCancelled(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return NewError(499, "client_closed", err.Error(), "", nil)
	}
	return nil
}

package db

import (
	"context"
	"fmt"
	"strings"
)

// SearchFTS runs an FTS5 BM25-ranked query against issues_fts, joins back to
// issues, and returns the top `limit` rows scoped to the given project. When
// includeDeleted is false, soft-deleted issues are filtered. The returned
// Score is the negated raw BM25 (so higher = better match); MatchedIn is
// derived from per-column MATCH subqueries since FTS5 highlight() returns
// NULL on contentless tables.
func (d *DB) SearchFTS(ctx context.Context, projectID int64, q string, limit int, includeDeleted bool) ([]SearchCandidate, error) {
	return d.searchFTS(ctx, searchFTSReq{
		projectID: projectID, q: q, mode: searchAll,
		limit: limit, includeDeleted: includeDeleted,
	})
}

// SearchFTSAny is like SearchFTS but joins query tokens with FTS5 OR rather
// than implicit AND. The look-alike soft-block uses this so candidate
// retrieval has high recall — similarity.Score is the actual gate, and the
// AND form prematurely filters near-duplicates that differ by one token.
func (d *DB) SearchFTSAny(ctx context.Context, projectID int64, q string, limit int, includeDeleted bool) ([]SearchCandidate, error) {
	return d.searchFTS(ctx, searchFTSReq{
		projectID: projectID, q: q, mode: searchAny,
		limit: limit, includeDeleted: includeDeleted,
	})
}

type searchMode int

const (
	searchAll searchMode = iota // implicit AND across query tokens
	searchAny                   // explicit OR across query tokens
)

// searchFTSReq bundles the inputs to the shared searchFTS implementation so
// the helper stays under the 5-positional-param limit.
type searchFTSReq struct {
	projectID      int64
	q              string
	mode           searchMode
	limit          int
	includeDeleted bool
}

func (d *DB) searchFTS(ctx context.Context, r searchFTSReq) ([]SearchCandidate, error) {
	q := strings.TrimSpace(r.q)
	if q == "" {
		return nil, nil
	}
	limit := r.limit
	if limit <= 0 {
		limit = 20
	}
	// Cap unbounded callers — the per-column subqueries make a huge limit
	// expensive, and the HTTP layer is the natural enforcer but defending
	// here is cheap.
	if limit > 200 {
		limit = 200
	}

	// Split the user query on whitespace, quote each whitespace-delimited
	// segment as an FTS5 phrase. This keeps every segment opaque to FTS5's
	// special characters (`:`, `*`, parens, `OR`/`AND`/`NOT` as bare words);
	// embedded double quotes are doubled per FTS5 quoting rules. The top-level
	// phrase joins quoted tokens by mode (space → implicit AND, " OR " →
	// explicit OR).
	var quoted []string
	for _, w := range strings.Fields(q) {
		quoted = append(quoted, `"`+strings.ReplaceAll(w, `"`, `""`)+`"`)
	}
	if len(quoted) == 0 {
		return nil, nil
	}
	var topPhrase string
	switch r.mode {
	case searchAny:
		topPhrase = strings.Join(quoted, " OR ")
	default:
		topPhrase = strings.Join(quoted, " ")
	}
	// Per-column MATCH always uses OR-of-tokens regardless of the top-level
	// mode: matched_in answers "which columns contributed at least one term?"
	// — under implicit-AND a cross-column match (e.g. title="login",
	// body="Safari" for "login Safari") is a valid hit but no single column
	// holds all the tokens, so an AND per-column subquery would mark every
	// column as not-matched and matched_in would be empty.
	colPhrase := topPhrase
	if r.mode == searchAll && len(quoted) > 1 {
		colPhrase = strings.Join(quoted, " OR ")
	}

	deletedFilter := "AND i.deleted_at IS NULL"
	if r.includeDeleted {
		deletedFilter = ""
	}
	// Per-column MATCH subqueries replace highlight() because issues_fts is
	// declared content='' (contentless), and highlight() returns NULL for every
	// column on contentless tables. Each subquery returns 1 if the row's
	// title/body/comments column matches the per-column phrase, 0 otherwise.
	query := fmt.Sprintf(`
		SELECT i.id, i.project_id, i.number, i.title, i.body, i.status,
		       i.closed_reason, i.owner, i.priority, i.author, i.created_at, i.updated_at,
		       i.closed_at, i.deleted_at,
		       bm25(issues_fts),
		       (issues_fts.rowid IN (SELECT rowid FROM issues_fts WHERE title    MATCH ?)) AS in_title,
		       (issues_fts.rowid IN (SELECT rowid FROM issues_fts WHERE body     MATCH ?)) AS in_body,
		       (issues_fts.rowid IN (SELECT rowid FROM issues_fts WHERE comments MATCH ?)) AS in_comments
		FROM issues_fts
		JOIN issues i ON i.id = issues_fts.rowid
		WHERE issues_fts MATCH ?
		  AND i.project_id = ?
		  %s
		ORDER BY bm25(issues_fts) ASC
		LIMIT %d`, deletedFilter, limit)

	// Bind order: colPhrase (×3 — title MATCH, body MATCH, comments MATCH),
	// then topPhrase (top-level MATCH), then projectID. Reordering the
	// SELECT/WHERE clauses without updating the bind list will silently
	// transpose binds.
	rows, err := d.QueryContext(ctx, query, colPhrase, colPhrase, colPhrase, topPhrase, r.projectID)
	if err != nil {
		return nil, fmt.Errorf("search fts: %w", err)
	}
	defer func() { _ = rows.Close() }()

	var out []SearchCandidate
	for rows.Next() {
		var (
			i                           Issue
			rawScore                    float64
			inTitle, inBody, inComments bool
		)
		if err := rows.Scan(&i.ID, &i.ProjectID, &i.Number, &i.Title, &i.Body, &i.Status,
			&i.ClosedReason, &i.Owner, &i.Priority, &i.Author, &i.CreatedAt, &i.UpdatedAt,
			&i.ClosedAt, &i.DeletedAt,
			&rawScore, &inTitle, &inBody, &inComments); err != nil {
			return nil, fmt.Errorf("scan search row: %w", err)
		}
		matched := make([]string, 0, 3)
		if inTitle {
			matched = append(matched, "title")
		}
		if inBody {
			matched = append(matched, "body")
		}
		if inComments {
			matched = append(matched, "comments")
		}
		// FTS5 BM25 returns negative numbers; invert so callers compare with
		// "higher = better" semantics.
		out = append(out, SearchCandidate{
			Issue:     i,
			Score:     -rawScore,
			MatchedIn: matched,
		})
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

